function readSetting(name) {
  try {
    if (typeof $env !== "undefined" && $env && $env[name]) return String($env[name]);
  } catch (error) {
    // n8n Cloud blocks $env inside nodes; fall through to Global Variables.
  }
  try {
    if (typeof $vars !== "undefined" && $vars && $vars[name]) return String($vars[name]);
  } catch (error) {
    // Self-hosted Community has no Global Variables; fall through.
  }
  return "";
}

function requireSetting(name) {
  const value = readSetting(name);
  if (!value) {
    throw new Error(
      name + " is not configured. Set it as an n8n environment variable ($env) or a Global Variable ($vars).",
    );
  }
  return value;
}

function sign(timestamp, body) {
  const secret = requireSetting("N8N_HMAC_SECRET");
  return require("crypto")
    .createHmac("sha256", secret)
    .update(timestamp + "." + body, "utf8")
    .digest("hex");
}

function convexBaseUrl() {
  return requireSetting("LENDLOOP_CONVEX_SITE_URL").replace(/\/+$/, "");
}

function escapeHtml(value) {
  return String(value === null || value === undefined ? "" : value).replace(
    /[&<>"']/g,
    (character) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character],
  );
}

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers["x-lendloop-timestamp"] || "").trim();
const signature = String(headers["x-lendloop-signature"] || "")
  .trim()
  .toLowerCase();

// The signature covers the exact bytes Convex sent, so read the raw body the
// Webhook node stored in the "data" binary property, never a re-serialised
// object. Three paths because the runtime differs: the editor's Code node
// exposes helpers.getBinaryDataBuffer, a task runner may only expose the
// binary item, and the last resort is whatever the webhook parsed.
let raw = "";
const binary = item.binary && item.binary.data ? item.binary.data : null;
try {
  if (this.helpers && typeof this.helpers.getBinaryDataBuffer === "function") {
    const buffer = await this.helpers.getBinaryDataBuffer(0, "data");
    if (buffer && buffer.length > 0) raw = buffer.toString("utf8");
  }
} catch (error) {
  // No helper in this runtime; fall through to the binary item.
}
if (!raw && binary && typeof binary.data === "string") {
  raw = Buffer.from(binary.data, "base64").toString("utf8");
}
if (!raw) {
  raw =
    typeof item.json.body === "string"
      ? item.json.body
      : JSON.stringify(item.json.body === undefined ? {} : item.json.body);
}

const secretConfigured = Boolean(readSetting("N8N_HMAC_SECRET"));
let reason = "";

if (!secretConfigured) {
  reason = "secret_not_configured";
} else if (!/^\d{13}$/.test(timestamp)) {
  reason = "malformed_timestamp";
} else if (!/^[0-9a-f]{64}$/.test(signature)) {
  reason = "malformed_signature";
} else if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) {
  reason = "timestamp_out_of_window";
} else {
  const expected = sign(timestamp, raw);
  const left = Buffer.from(expected, "utf8");
  const right = Buffer.from(signature, "utf8");
  if (left.length !== right.length || !require("crypto").timingSafeEqual(left, right)) {
    reason = "signature_mismatch";
  }
}

let payload = null;
try {
  payload = JSON.parse(raw);
} catch (error) {
  if (!reason) reason = "invalid_json";
}

return [{ json: { verified: reason === "", reason, payload, receivedAt: Date.now() } }];

