const payload = $input.first().json.payload || {};
const tool = payload.tool || {};
const borrower = payload.borrower || {};
const owner = payload.owner || {};
const toolName = tool.name || "a tool";
const borrowerName = borrower.name || borrower.email || "A neighbour";
const ownerName = owner.name || "the owner";

const startDate = payload.startDate || "";
const endDate = payload.endDate || "";
const note = payload.message ? String(payload.message) : "";

const subject = "LendLoop: " + toolName + " requested by " + borrowerName;
const lines = [
  "Hi " + ownerName + ",",
  "",
  borrowerName + " asked to borrow " + toolName + " from " + startDate + " to " + endDate + ".",
  note ? "Message: " + note : "",
  "",
  "Open LendLoop to approve or decline the request.",
].filter((line) => line !== "");

const html = [
  "<p>Hi " + escapeHtml(ownerName) + ",</p>",
  "<p><strong>" + escapeHtml(borrowerName) + "</strong> asked to borrow <strong>" + escapeHtml(toolName) + "</strong> from " + escapeHtml(startDate) + " to " + escapeHtml(endDate) + ".</p>",
  note ? "<p>Message: " + escapeHtml(note) + "</p>" : "",
  "<p>Open LendLoop to approve or decline the request.</p>",
].join("");

return [
  {
    json: {
      requestId: payload.requestId || "",
      idempotencyKey: payload.idempotencyKey || "",
      from: readSetting("LENDLOOP_FROM_EMAIL") || "LendLoop <notifications@example.com>",
      to: owner.email || "",
      subject,
      text: lines.join("\n"),
      html,
    },
  },
];
